#!/usr/bin/env node
/**
 * Runs one of the factory hooks (copied unchanged from .claude/hooks/) only in
 * an app generated by hipster-stack, so the plugin stays silent in every other
 * repository. The hook itself reads the event from stdin.
 *
 *   node when-app.mjs lint-edited-file.mjs | execution-state-guard.mjs
 */
import { existsSync } from "node:fs";
import path from "node:path";

const HOOKS = new Set(["lint-edited-file.mjs", "execution-state-guard.mjs"]);
const hook = process.argv[2];
if (!HOOKS.has(hook)) {
  process.stderr.write(`when-app: unknown hook ${hook}\n`);
  process.exit(1);
}

const projectDir = process.env.CLAUDE_PROJECT_DIR || process.cwd();
if (!existsSync(path.join(projectDir, "hipster.json"))) process.exit(0);

await import(new URL(`./${hook}`, import.meta.url).href);
